}

function isDateLike(value: unknown): value is string | number {
  if (typeof value !== 'string' && typeof value !== 'number') return false;
  return Number.isFinite(new Date(value).getTime());
}

function validateCursor(before: unknown): string | undefined {
  if (before === undefined) return undefined;
  if (typeof before !== 'object' || before === null) return 'list_sessions before must be an object';
  const {sessionId, updatedAt} = before as Record<string, unknown>;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > 128) {
    return 'list_sessions before.sessionId must be 1-128 characters';
  }
  if (!isDateLike(updatedAt)) return 'list_sessions before.updatedAt must be a date string or number';
  return undefined;
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const error = validateLimit(message.limit) ?? validateCursor(message.before);
  if (error !== undefined) return {valid: false, error};

  const listRequest: ListSessionsMessage = {type: 'list_sessions'};
  if (message.limit !== undefined) listRequest.limit = message.limit as number;
